// Versioned registry: coexistence + deprecation lifecycle (plain JS)
function makeRegistry() {
  const tools = new Map(); // name -> [{version, fn, deprecated, deadline}]
  return {
    register(name, version, fn, meta = {}) { /* push version entry */ },
    resolve(name, want) {
      const versions = tools.get(name) || [];
      const pick = want ? versions.find((v) => v.version === want)
        : [...versions].reverse().find((v) => !v.deprecated) || versions[versions.length - 1];
      if (pick && pick.deprecated) pick.warned = (pick.warned || 0) + 1;
      return pick || null;
    },
    discover() { return [...tools].map(([n, vs]) => ({ name: n, versions: vs.map((v) => v.version + (v.deprecated ? " (deprecated)" : "")) })); },
  };
}
