function makeRegistry() {
  const tools = new Map();
  return {
    register(name, version, fn, dep) {
      if (!tools.has(name)) tools.set(name, []);
      tools.get(name).push({ version, fn, deprecated: !!dep });
    },
    resolve(name, want) {
      const vs = tools.get(name) || [];
      const pick = want ? vs.find((v) => v.version === want) : [...vs].reverse().find((v) => !v.deprecated) || vs[vs.length - 1];
      return pick ? pick.version + (pick.deprecated ? '!' : '') : null;
    },
  };
}
